func (c ServerConfig) Validate() error {
	host, _, _ := net.SplitHostPort(c.Addr)
	exposed := host != "" && host != "127.0.0.1" && host != "localhost" && host != "::1"
	if c.Token == "" || c.Token == "dev-token" {
