func OpenStore(path string) (*Store, error) {
	dialect := dbDialect(path)
	if dialect == "sqlite" && path != "" && path != ":memory:" {
		if err := ensureDir(filepath.Dir(path)); err != nil {
			return nil, err
		}
	}
	driver := "sqlite"
	if dialect == "postgres" {
		driver = "pgx"
	}
	db, err := sql.Open(driver, path)
	if err != nil {
		return nil, err
	}
	if dialect == "postgres" {
